import{_ as a}from"./chunks/live.DqM0EmIK.js";import{_ as i,o as t,c as r,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Live: живая карта","description":"","frontmatter":{"pageId":"players/live","contentRevision":1},"headers":[],"relativePath":"ru/players/live.md","filePath":"ru/players/live.md"}'),o={name:"ru/players/live.md"};function s(n,e,p,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="live-живая-карта" tabindex="-1">Live: живая карта <a class="header-anchor" href="#live-живая-карта" aria-label="Permalink to &quot;Live: живая карта&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><img class="wiki-art" src="'+a+'" alt="Владелец симулирует карту; гость передаёт приказы и получает обновления." width="960" height="440"><p class="wiki-caption">Владелец симулирует карту; гость передаёт приказы и получает обновления.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Гость предлагает live-рейд или live-визит с выбранными пешками. Хозяин принимает приглашение (по умолчанию 60 секунд на ответ). После загрузки гость видит зеркало карты; команды исполняются у хозяина, который остаётся авторитетом симуляции и сейва.</p><p>Скорость согласуется по более медленному запросу. Гость использует собственный бюджет пауз (по умолчанию 10 по 60 секунд). Пауза на письмах учитывает более строгую настройку участников. Для окончания гость выходит, хозяин может прервать сессию.</p><p>При потере связи дождись PeerBack/переподключения. Повторы продолжаются каждые 60 секунд; после двух минут предлагается выход в меню. Рассинхронизация требует нового снимка, а не ручной правки карты.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Хозяин должен оставаться онлайн. Live не создаёт самостоятельную вторую версию сейва. Не завершай сессию удалением журналов или принудительной выдачей пешек.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./coop">Постоянная совместная колония</a></li><li><a href="./raids-incidents">Рейды и платные события</a></li><li><a href="./troubleshooting">Проблемы игрока</a></li></ul>',12)])])}const f=i(o,[["render",s]]);export{u as __pageData,f as default};
